TLM.f("Sancti/11-02m1",{"officium":"In Commemoratione Omnium Fidelium Defunctorum Ad primam Missam","rule":["ex C9","no Gloria","no Credo","Prefatio=Defunctorum","multiple3","Sequentia"],"ruleInherited":["no Gloria","no Credo","Prefatio=Defunctorum","Sequentia"],"fallback":"Commune/C9","from":{"Introitus":"Commune/C9","Graduale":"Commune/C9","Sequentia":"Commune/C9","Offertorium":"Commune/C9","Communio":"Commune/C9"},"sections":{"Introitus":[{"k":"ref","la":"4 Esdr 2:34; 2:35"},{"k":"text","la":"Réquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis."},{"k":"ref","la":"Ps 64:2-3"},{"k":"text","la":"Te decet hymnus, Deus, in Sion, et tibi reddétur votum in Jerúsalem: exáudi oratiónem meam, ad te omnis caro véniet."},{"k":"text","la":"Réquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis."}],"Oratio":[{"k":"text","la":"Fidélium, Deus, ómnium Cónditor et Redémptor: animábus famulórum famularúmque tuárum remissiónem cunctórum tríbue peccatórum; ut indulgéntiam, quam semper optavérunt, piis supplicatiónibus consequántur:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 15:51-57"},{"k":"text","la":"Fratres: Ecce, mystérium vobis dico: Omnes quidem resurgámus, sed non omnes immutábimur. In moménto, in ictu óculi, in novíssima tuba: canet enim tuba, et mórtui resúrgent incorrúpti: et nos immutábimur. Opórtet enim corruptíbile hoc induere incorruptiónem: et mortále hoc indúere immortalitátem. Cum autem mortále hoc indúerit immortalitátem, tunc fiet sermo, qui scriptus est: Absórpta est mors in victória. Ubi est, mors, victória tua? Ubi est, mors, stímulus tuus? Stímulus autem mortis peccátum est: virtus vero peccáti lex. Deo autem grátias, qui dedit nobis victóriam per Dóminum nostrum Jesum Christum."}],"Graduale":[{"k":"ref","la":"4 Esdr 2:34-35"},{"k":"text","la":"Réquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis."},{"k":"ref","la":"Ps 111:7"},{"k":"text","la":"In memória ætérna erit justus: ab auditióne mala non timébit.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"text","la":"Absólve, Dómine, ánimas ómnium fidélium ab omni vínculo delictórum."},{"k":"text","la":"Et grátia tua illis succurrénte, mereántur evádere judícium ultiónis.","mark":"V"},{"k":"text","la":"Et lucis ætérnæ beatitúdine pérfrui.","mark":"V"}],"Sequentia":[{"k":"text","la":"Dies iræ, dies illa"},{"k":"text","la":"Solvet sæclum in favílla:"},{"k":"text","la":"Teste David cum Sibýlla."},{"k":"sep"},{"k":"text","la":"Quantus tremor est futúrus,"},{"k":"text","la":"Quando judex est ventúrus,"},{"k":"text","la":"Cuncta stricte discussúrus!"},{"k":"sep"},{"k":"text","la":"Tuba mirum spargens sonum"},{"k":"text","la":"Per sepúlcra regiónum,"},{"k":"text","la":"Coget omnes ante thronum."},{"k":"sep"},{"k":"text","la":"Mors stupébit et natúra,"},{"k":"text","la":"Cum resúrget creatúra,"},{"k":"text","la":"Judicánti responsúra."},{"k":"sep"},{"k":"text","la":"Liber scriptus proferétur,"},{"k":"text","la":"In quo totum continétur,"},{"k":"text","la":"Unde mundus judicétur."},{"k":"sep"},{"k":"text","la":"Judex ergo cum sedébit,"},{"k":"text","la":"Quidquid latet, apparébit:"},{"k":"text","la":"Nil inúltum remanébit."},{"k":"sep"},{"k":"text","la":"Quid sum miser tunc dictúrus?"},{"k":"text","la":"Quem patrónum rogatúrus,"},{"k":"text","la":"Cum vix justus sit secúrus?"},{"k":"sep"},{"k":"text","la":"Rex treméndæ majestátis,"},{"k":"text","la":"Qui salvándos salvas gratis,"},{"k":"text","la":"Salva me, fons pietátis."},{"k":"sep"},{"k":"text","la":"Recordáre, Jesu pie,"},{"k":"text","la":"Quod sum causa tuæ viæ:"},{"k":"text","la":"Ne me perdas illa die."},{"k":"sep"},{"k":"text","la":"Quærens me, sedísti lassus:"},{"k":"text","la":"Redemísti Crucem passus:"},{"k":"text","la":"Tantus labor non sit cassus."},{"k":"sep"},{"k":"text","la":"Juste judex ultiónis,"},{"k":"text","la":"Donum fac remissiónis"},{"k":"text","la":"Ante diem ratiónis."},{"k":"sep"},{"k":"text","la":"Ingemísco, tamquam reus:"},{"k":"text","la":"Culpa rubet vultus meus:"},{"k":"text","la":"Supplicánti parce, Deus."},{"k":"sep"},{"k":"text","la":"Qui Maríam absolvísti,"},{"k":"text","la":"Et latrónem exaudísti,"},{"k":"text","la":"Mihi quoque spem dedísti."},{"k":"sep"},{"k":"text","la":"Preces meæ non sunt dignæ:"},{"k":"text","la":"Sed tu bonus fac benígne,"},{"k":"text","la":"Ne perénni cremer igne."},{"k":"sep"},{"k":"text","la":"Inter oves locum præsta,"},{"k":"text","la":"Et ab hœdis me sequéstra,"},{"k":"text","la":"Státuens in parte dextra."},{"k":"sep"},{"k":"text","la":"Confutátis maledíctis,"},{"k":"text","la":"Flammis ácribus addíctis:"},{"k":"text","la":"Voca me cum benedíctis."},{"k":"sep"},{"k":"text","la":"Oro supplex et acclínis,"},{"k":"text","la":"Cor contrítum quasi cinis:"},{"k":"text","la":"Gere curam mei finis."},{"k":"sep"},{"k":"text","la":"Lacrimósa dies illa,"},{"k":"text","la":"Qua resúrget ex favílla"},{"k":"text","la":"Judicándus homo reus."},{"k":"sep"},{"k":"text","la":"Huic ergo parce, Deus:"},{"k":"text","la":"Pie Jesu Dómine,"},{"k":"text","la":"Dona eis réquiem."},{"k":"text","la":"Amen."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 5:25-29"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis Judæórum: Amen, amen, dico vobis, quia venit hora, et nunc est, quando mórtui áudient vocem Fílii Dei: et qui audíerint, vivent. Sicut enim Pater habet vitam in semetípso, sic dedit et Fílio habére vitam in semetípso: et potestátem dedit ei judícium fácere, quia Fílius hóminis est. Nolíte mirári hoc, quia venit hora, in qua omnes, qui in monuméntis sunt, áudient vocem Fílii Dei: et procédent, qui bona fecérunt, in resurrectiónem vitæ: qui vero mala egérunt, in resurrectiónem judícii."}],"Offertorium":[{"k":"text","la":"Dómine Jesu Christe, Rex glóriæ, líbera ánimas ómnium fidélium defunctórum de pœnis inférni et de profúndo lacu: líbera eas de ore leónis, ne absórbeat eas tártarus, ne cadant in obscúrum: sed sígnifer sanctus Míchaël repræséntet eas in lucem sanctam:"},{"k":"text","la":"* Quam olim Abrahæ promisísti et sémini ejus."},{"k":"text","la":"Hóstias et preces tibi, Dómine, laudis offérimus: tu súscipe pro animábus illis, quarum hódie memóriam fácimus: fac eas, Dómine, de morte transíre ad vitam.","mark":"V"},{"k":"text","la":"* Quam olim Abrahæ promisísti et sémini ejus."}],"Secreta":[{"k":"text","la":"Hóstias, quǽsumus, Dómine, quas tibi pro animábus famulórum famularúmque tuárum offérimus, propitiátus inténde: ut, quibus fídei christiánæ méritum contulísti, dones et prǽmium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"4 Esdr 2:35; 2:34"},{"k":"text","la":"Lux ætérna lúceat eis, Dómine:"},{"k":"text","la":"* Cum Sanctis tuis in ætérnum: quia pius es."},{"k":"text","la":"Requiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis.","mark":"V"},{"k":"text","la":"* Cum Sanctis tuis in ætérnum: quia pius es."}],"Postcommunio":[{"k":"text","la":"Animábus, quǽsumus, Dómine, famulórum famularúmque tuárum orátio profíciat supplicántium: ut eas et a peccátis ómnibus éxuas, et tuæ redemptiónis fácias esse partícipes:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"32e7f7f366bbed69":{"t":"4 Ezr 2, 34 i 35, Ps 64, 2-3\n(4 Ezr 2, 34 i 35) Pokoj vječni daruj im Gospodine, i svjetlost vječna svijetlila njima. (Ps 64, 2-3) Tebi Bože, pripada pjesma na Sionu, i tebi se izvršuje zavjet u Jeruzalemu; usliši moju molitvu, k tebi dolazi svako tijelo. (4 Ezr 2, 34 i 35) Pokoj vječni daruj im Gospodine, i svjetlost vječna svijetlila njima. [izostavlja se Slava Ocu] [NAPOMENA: 4 Ezr je apokrifna knjiga koja je sastavni dio Jeronimove Vulgate (ne i Septuaginte), a preuzeta je iz starijih latinskih verzija tzv. Vetus Latina. Knjige 1 Ezr i 2 Ezr su kanonske, te se alternativno imenuju i kao Ezr i Neh (Ezra i Nehemija). Misal iz 1962 napravljen je po posttridentskoj inačici Vulgate, tzv. Klementini (po papi Klementu VIII, 1592-1605) u kojoj se 3 Ezr i 4 Ezr te druge apokrifne knjige nalaze na kraju u dodatku. U novoj verziji, tzv. Vulgata Nova (1979, 1986) apokrifne su knjige izostavljene.]","v":"iv esdr et → ∅; iv esdr et → ∅","kn":"Pokoj vječni daruj im. Gospodine, i svjetlost vječna neka im svijetli. (Ps. 64, 2, 3). Tebi pjevamo Bože, na Sionu, Tebi prinosimo naše zavjete u Jeruzalemu; usliši molitvu moju; k Tebi će doći svaki smrtnik. Pokoj vječni . . .","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"4de5d00f5650cdb4":{"t":"<i>Pomolimo se</i>.\nBože, stvoritelju i otkupitelju svih vjernika, dušama slugu i službenica svojih podaj oproštenje svih grijeha, da pobožnim molitvama postignu pomilovanje, koje su uvijek željeli:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, Stvoritelju i otkupitelju svih vjernika, podaj dušama Tvojih slugu i službenica oprošteni e svih grijeha, što su ga vazda željeli, koji živiš i kraljuješ . . .","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"f53277b66aed0928":{"t":"1 Kor 15, 51-57\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, evo vam otkrivam tajnu: Svi ćemo zaista uskrsnuti, ali se svi nećemo promijeniti. U jedan hip, u tren oka, na glas posljednje trublje: Zatrubit će trublja i mrtvi će uskrsnuti neraspadljivi, a mi ćemo se promijeniti. Jer ovo raspadljivo tijelo treba da se obuče u neraspadljivost, i ovo smrtno tijelo da se obuče u besmrtnost, tada će se ispuniti riječ što je napisana: Poražena je smrt pobjedom. Gdje je smrti, tvoja pobjeda? Gdje je smrti, tvoj žalac? Žalac je smrti grijeh, a snaga je grijeha u zakonu. Ali hvala Bogu, koji nam dade pobjedu po našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice hl. Pavla apostola Korinćanima (I, 15, 51-57). Braćo! Evo objavljujem vam tajnu: Svi ćemo zaista uskrsnuti, ali se svi ne ćemo promijeniti. Na jedamput, u tren oka, na glas posljednje trublje (jer će se oglasiti trublja), mrtvi će uskrsnuti neraspadljivi, a mi ćemo se promijeniti. Zato treba da se ovo raspadljivo tijelo obuče u neraspadljivost i ovo smrtno u besmrtnost. Kad ovo smrtno tijelo bude besmrtno, tada će se ispuniti riječ Pisma: Smrt je bila uništena pobjedom. Smrti, gdje je tvoja pobjeda? Smrti, gdje je tvoj žalac? žalac smrti je grijeh, a sila grijeha; je zakon. Hvala Bogu, koji nam je udijelio pobjedu po Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"45cebb65b408d0d1":{"t":"4 Ezr 2, 34 i 35, Ps 111, 7\n(4 Ezr 2, 34 i 35) Pokoj vječni daruj im, Gospodine, i svjetlost vječna svijetlila njima. (Ps 111, 7) Pravednik će živjeti u vječnoj uspomeni, i neće se bojati zla glasa.\n\nOdriješi, Gospodine, duše svih vjernih mrtvih od svake veze grijeha. I daj da pomoću tvojega milosrđa zavrijede izmaći sudu osvete i uživati blaženstvo vječnoga svjetla.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.96)"},"f5831093ed7947a9":{"t":"U dan onaj, u dan gnjeva/ Ognjem svijet će sav da sijeva/ Sa Sibilom David pjeva. <i>\n</i>\nKolik strah će na sve pasti/ Kada Sudac s višnjom vlasti/ Dođe pretrest ljudske strasti! <i>\n</i>\nTrublje čudan zvuk romoni,/ U sva groblja budeć roni/ I pred prijesto mrtve goni. <i>\n</i>\nSmrt i narav zadivljene/ Motre ljude oživljene/ Na sud Božji sakupljene. <i>\n</i>\nOtvara se knjiga jada,/ Knjiga ljudskog grješnog rada/ Što će vagnut biti sada. <i>\n</i>\nKada Sudac sudit stane,/ Sve će tajne biti znane,/ Sve grehote pokarane. <i>\n</i>\nŠto ću jadan tada zborit?/ Komu ću se zagovorit?/ Gdje i dobre strah će morit? <i>\n</i>\nKralju strašne veličine,/ Dajuć spas ko' dar s visine,/ Spasi mene, pun miline! <i>\n</i>\nSjeti se o Spase mio,/ Da si za me putnik bio,/ Ne daj mi u paklu dio. <i>\n</i>\nIštući me trudan hoda,/ Spasenje mi križem poda,/ Zar da bude to bez ploda? <i>\n</i>\nVišnji Suče, pravdo stroga,/ Sagrješenja prosti mnoga,/ Prije dana osvetnoga. <i>\n</i>\nUzdišem ko' krivac hudi/ Grijeh mi stidom lice rudi,/ Dršćuć prosim: ne osudi! <i>\n</i>\nMariju si opravdao,/ Raj zločincu obećao/ Pa i meni nadu dao. <i>\n</i>\nMolitva mi nema moći,/ Al' ti blag si, ne daj poći/ U plam vječni mojoj zloći. <i>\n</i>\nK ovcama me svojim kreni,/ Među jarad ne daj meni,/ S desne strane mene djeni. <i>\n</i>\nKad potreseš grješnim svijetom/ Plamenu ga predaš kletom,/ Zovni mene s vojskom svetom. <i>\n</i>\nMolim u svoj sniženosti,/ Srca puna skrušenosti:/ Daj mi umrijet u milosti. <i>\n</i>\nAvaj dana suza, straha,/ Kada griješni stvor iz praha/ Pođe k sudu posljednjemu! <i>\n</i>\nSlatki Spase, prosti njemu!/ Milo duše pogledaj,/ Pokoj vječni njima daj! <i>\n</i>\n<i>amen</i>."},"457252f59aa7cf14":{"t":"Iv 5, 25-29\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme, reče Isus mnoštvu Židova: Zaista, zaista kažem vam, dolazi čas i već je tu, kad će mrtvi čuti glas Sina Božjega, i koji ga budu čuli, živjet će. Kao što Otac ima život u sebi, tako je i Sinu dao da ima život u sebi. Dao mu je i vlast da sudi, jer je Sin Čovječji. Ne čudite se tomu, jer dolazi čas, kada će svi, koji su u grobovima, čuti glas Sina Božjega; i oni, koji su činili dobro, uskrsnut će na uskrsnuće života, a koji su činili zlo na uskrsnuće osuđenja.","kn":"t Slijedi sv. evanđelje po Ivanu (5, 25-29). U ono vrijeme reče Isus židovskoniu narodu: Zaista, zaista vam kažem, da dolazi čas 1 već je tu, kad će mrtvi čuti glas Sina Božjega i koji budu čuli, oživjet će. Jer kao što Otac ima život u samomu sebi, tako je i Sinu dao, da ima život u samomu sebi. I dao mu je vlast da sudi, jer je Sin čovječji. Ne čudite se ovomu, jer ide čas, kada će svi, koji su u grobovima, čuti glas Sina Božjega. I koji su činili dobro, uskrsnut će na život, a koji su činili zlo, uskrsnut će na osudu.","knRef":"Kniewald 1942, str. 762–763 (snimka 382) (OCR)"},"d0530a95e89f4e92":{"t":"Gospodine Isuse Kriste, kralju slave, izbavi duše svih vjernih mrtvih od paklenih kazni i iz dubokoga bezdna; izbavi ih od usta lava da ih ne proždre pakao, da ne upadnu u tamu, nego da ih zastavonoša sveti Mihovil povede u svetu svjetlost koju si nekoć obećao Abrahamu i njegovu potomstvu. – Prinosimo ti, Gospodine, žrtve i molitve hvale; primi ih za one duše kojih se danas spominjemo; učini, Gospodine, da iz smrti prijeđu u život, što si ga nekoć obećao Abrahamu i njegovu potomstvu.","kn":"Gospodine Isuse Kriste, kralju slave, izbavi duše svih vjernih mrtvih od paklenih kaznS, iz dubokoga bezdna, izbavi ih iz usta lavljih, da ih ne proguta dubina, da ne padnu u tamu, nego da ih Tvoj stjegonoša sveti Mihovil povede u sveto svijetlo, što si ga nekoć obećao Abrahamu i njegovu potomstvu. Prinosimo Ti, Gospodine, žrtve, molitve i hvale, da ih primiš za one duše, kojih se danas spominjemo. Učini, Gospodine, da iz .smrti prijeđu u život, što si ga nekoć obećao Abrahamu i njegovu potomstvu.","knRef":"Kniewald 1942, str. 762–763 (snimka 382) (OCR)"},"a14b8a6a6f67fbc9":{"t":"Milostivo pogledaj, molimo, Gospodine, na žrtve što ti ih prinosimo za duše tvojih slugu i službenica, da onima kojima si dao zaslugu kršćanske vjere daruješ i nagradu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Obazri se, molimo Te, blagi Gospodine, na žrtve, što Ti ih prinosimo za duše Tvojih sluga i službenica, da im daruješ 1 nagradu, kako si im darovao zaslugu kršćanske vjere, po G. n.","knRef":"Kniewald 1942, str. 762–763 (snimka 382) (OCR)"},"0c98ba500896375d":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – U njemu nam zasja nada blaženog uskrsnuća. Koji tuguju zbog neizbježne smrti, njih neka tješi obećanje buduće besmrtnosti. Jer tvojim se vjernima, Gospodine, život mijenja a ne oduzima, i pošto se raspadne dom ovozemnoga boravka, stječe se vječno prebivalište na nebesima. – stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predsldvlje. Uistinu je dostojno i pnavedno, pravo i spasonosno, da Ti uvijek, i svagdje hvale uzdajemo, Gospodine sveti. Oče .Svemogući, vječni Bože, po Kristu, Gospodinu našemu; Jer nam je u njemu zasjala nada blaženoga uskrsnuća, te pramda nas ožalošćuje udes umiranja, ipak nas tješi obećanje budućeg uskrsnuća. Jer Tvojim se vjernicima. Gospodine, život mijenja, ne oduzimlje; i kad še razori kuća ovoga zemaljskoga boravka, pripravlja se vječni stan u nebesima. I zato pjevamo, pjesmu slave Tvoje s anđelima i s arkanđelima, s Prijestoljima i gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 768–769 (snimka 385) (OCR)"},"421af3c8576a23ea":{"t":"4 Ezr 2, 35 i 34\nSvjetlost vječna svijetlila im, Gospodine, s tvojim svetima u vijeke jer ti si milosrdan. Pokoj vječni daruj im, Gospodine, i svjetlost vječna svijetlila njima, s tvojim svetima u vijeke, jer ti si milosrdan.","kn":"Svjetlost vječna neka im svijetli, Gospodine, -S Tvojim svetima u sve vijeke, jer Ti si blag. Pokoj vječni daruj im Goispodine 1 svjetlost vječna neka im svijetli s Tvojim svetima u sve .vijeke, jer Ti Bi blag.","knRef":"Kniewald 1942, str. 762–763 (snimka 382) (OCR)"},"e6bf642b47515f56":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da naše ponizne molitve pomognu dušama tvojih slugu i službenica, te da ih očistiš od svih grijeha i učiniš dionicima tvoga otkupljenja:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da naše ponizne molitve pomognu dušama Tvojih sluga i službenica, te ih očistiš od svih grijeha i učiniš dionicima Tvoga otkupljenja, koji živiš i kraljuješ.","knRef":"Kniewald 1942, str. 762–763 (snimka 382) (OCR)"}}});
